def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    by_x = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        l, r, x = data[p] - 1, data[p + 1] - 1, data[p + 2] - 1
        p += 3
        by_x[x].append((l, r))

    # For each x and right endpoint r, store the largest left endpoint
    # among constraints with argmax position x and right endpoint <= r.
    bad = [[-1] * n for _ in range(n)]
    for x in range(n):
        ends = [-1] * n
        for l, r in by_x[x]:
            if l > ends[r]:
                ends[r] = l
        cur = -1
        row = bad[x]
        for r in range(n):
            if ends[r] > cur:
                cur = ends[r]
            row[r] = cur

    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        prev = comb[i - 1] if i else None
        if i:
            row = comb[i]
            for j in range(1, i):
                row[j] = (prev[j - 1] + prev[j]) % MOD

    dp = [[0] * n for _ in range(n)]
    for length in range(1, n + 1):
        weights = comb[length - 1]
        for l in range(n - length + 1):
            r = l + length - 1
            val = 0
            for k in range(l, r + 1):
                if bad[k][r] >= l:
                    continue
                a = dp[l][k - 1] if k > l else 1
                b = dp[k + 1][r] if k < r else 1
                val += weights[k - l] * a * b
            dp[l][r] = val % MOD
    print(dp[0][n - 1])

if __name__ == '__main__':
    main()

