import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    A = data[1:]

    factors = []
    all_primes = set()
    for x in A:
        d = {}
        q = x
        p = 2
        while p * p <= q:
            if q % p == 0:
                e = 0
                while q % p == 0:
                    q //= p
                    e += 1
                d[p] = e
                all_primes.add(p)
            p += 1
        if q > 1:
            d[q] = 1
            all_primes.add(q)
        factors.append(d)

    answer = 1
    for prime in all_primes:
        # State: (current cumulative exponent, minimum cumulative exponent).
        # The stored weight is p^(sum of the cumulative exponents so far).
        dp = {(0, 0): 1}
        for d in factors:
            e = d.get(prime, 0)
            nxt = {}
            for (height, low), value in dp.items():
                if e:
                    next_heights = (height + e, height - e)
                else:
                    next_heights = (height,)
                for nh in next_heights:
                    nl = min(low, nh)
                    key = (nh, nl)
                    nxt[key] = (nxt.get(key, 0) + value * pow(prime, nh, MOD)) % MOD
            dp = nxt

        # Subtracting the path minimum from every one of the n vertex exponents
        # multiplies its score by p^(-n*minimum).
        contribution = 0
        for (height, low), value in dp.items():
            contribution += value * pow(prime, -n * low, MOD)
        answer = answer * (contribution % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

