from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending_at = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            left, right = sorted((a, b))
            ending_at[right].append((left, idx))

        largest = second_largest = 0
        largest_id = -1
        improvement = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in ending_at[right]:
                if left > largest:
                    second_largest = largest
                    largest = left
                    largest_id = idx
                elif left > second_largest:
                    second_largest = left

            # For subarrays ending here, valid starts are strictly greater
            # than the largest left endpoint among conflicts ending so far.
            total += right - largest

            # Removing the unique largest conflict relaxes the start bound
            # from largest to second_largest.
            if largest_id != -1:
                improvement[largest_id] += largest - second_largest

        return total + max(improvement)

