from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at=[[] for _ in range(n+1)]
        for idx,(a,b) in enumerate(conflictingPairs):
            l,r=sorted((a,b))
            at[r].append((l,idx))
        top=second=0
        top_id=-1
        gain=[0]*len(conflictingPairs)
        base=0
        for r in range(1,n+1):
            for l,idx in at[r]:
                if l>top:
                    second=top
                    top=l
                    top_id=idx
                elif l>second:
                    second=l
            base += r-top
            if top_id>=0:
                gain[top_id]+=top-second
        return base+max(gain)

