    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    edges = []
    for _ in range(m):
        a, b, c = next(it) - 1, next(it) - 1, next(it)
        edges.append((a, b, c))

    queries = []
    deleted = set()
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            queries.append((1, e))
            deleted.add(e)
        else:
            x, y = next(it) - 1, next(it) - 1
            queries.append((2, x, y))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for eid, (a, b, c) in enumerate(edges):
        if eid not in deleted:
            dist[a][b] = dist[b][a] = c

    # APSP in the graph after all closures.
    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            row_i = dist[i]
            for j in range(n):
                candidate = dik + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            value = dist[query[1]][query[2]]
            answers.append(str(-1 if value == inf else value))
        else:
            a, b, c = edges[query[1]]
            # Distances before adding this road; snapshot the needed row/column.
            col_a = [dist[i][a] for i in range(n)]
            col_b = [dist[i][b] for i in range(n)]
            row_a = dist[a][:]
            row_b = dist[b][:]
            for i in range(n):
                through_a = col_a[i] + c
                through_b = col_b[i] + c
                row = dist[i]
                for j in range(n):
                    candidate = through_a + row_b[j]
                    if candidate < row[j]:
                        row[j] = candidate
                    candidate = through_b + row_a[j]
                    if candidate < row[j]:
                        row[j] = candidate

    print("\n".join(reversed(answers)))

if __name__ == "__main__":
