import sys
import math


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    processes = [data[2 + 4 * i: 6 + 4 * i] for i in range(n)]

    def minimum_cost(a, p, b, q, target):
        g = math.gcd(a, b)
        best = 10**30

        # Replace a block of A/g T-machines with B/g S-machines,
        # or vice versa, so only a bounded number of one type is needed.
        if p * (b // g) <= q * (a // g):
            for y in range(a // g):
                remaining = target - b * y
                x = max(0, (remaining + a - 1) // a)
                best = min(best, x * p + y * q)
        else:
            for x in range(b // g):
                remaining = target - a * x
                y = max(0, (remaining + b - 1) // b)
                best = min(best, x * p + y * q)
        return best

    def feasible(target):
        total = 0
        for a, p, b, q in processes:
            total += minimum_cost(a, p, b, q, target)
            if total > budget:
                return False
        return True

    max_rate = max(max(a, b) for a, p, b, q in processes)
    min_price = min(min(p, q) for a, p, b, q in processes)
    low = 0
