class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        m=len(s)
        depth=[0]*(m+1)
        for x in range(2,m+1):
            v=x
            d=0
            while v!=1:
                v=v.bit_count()
                d+=1
            depth[x]=d
        fact=[1]*(m+1)
        for i in range(1,m+1):
            fact[i]=fact[i-1]*i%MOD
        invfact=[1]*(m+1)
        invfact[m]=pow(fact[m],MOD-2,MOD)
        for i in range(m,0,-1):
            invfact[i-1]=invfact[i]*i%MOD
        def comb(a,b):
            if b<0 or b>a:
                return 0
            return fact[a]*invfact[b]%MOD*invfact[a-b]%MOD
        ans=0
        for ones in range(1,m+1):
            if depth[ones]+1>k:
                continue
            remain=ones
            for i,ch in enumerate(s):
                if ch=='1':
                    ans+=comb(m-i-1,remain)
                    if ans>=MOD:
                        ans-=MOD
                    remain-=1
                    if remain<0:
                        break
        return ans%MOD

