from collections import deque

def solve():
    input = sys.stdin.readline
    n = int(input())
    g = [input().strip() for _ in range(n)]

    inc = [[[] for _ in range(26)] for _ in range(n)]
    out = [[[] for _ in range(26)] for _ in range(n)]
    for i in range(n):
        for j, ch in enumerate(g[i]):
            if ch != '-':
                c = ord(ch) - 97
                out[i][c].append(j)
                inc[j][c].append(i)

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    q = deque()
    for i in range(n):
        dist[i][i] = 0
        q.append((i, i))
    for i in range(n):
        for j, ch in enumerate(g[i]):
            if ch != '-' and dist[i][j] == inf:
                dist[i][j] = 1
                q.append((i, j))

    finite = sum(1 for row in dist for x in row if x != inf)
    max_dist = 1 if finite else 0
    while q:
        i, j = q.popleft()
        nd = dist[i][j] + 2
        # No remaining state can improve when all pairs are already solved.
        if finite == n * n and nd >= max_dist:
            break
        for c in range(26):
            for a in inc[i][c]:
                row = dist[a]
                for b in out[j][c]:
                    if row[b] == inf:
                        row[b] = nd
                        finite += 1
                        if nd > max_dist:
                            max_dist = nd
                        q.append((a, b))

    print('\n'.join(' '.join(str(-1 if x == inf else x) for x in row) for row in dist))

