import sys
import heapq


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    H, W, X = data[:3]
    P, Q = data[3] - 1, data[4] - 1
    strengths = data[5:]

    power = strengths[P * W + Q]
    seen = bytearray(H * W)
    seen[P * W + Q] = 1
    frontier = []

    def add(r, c):
        idx = r * W + c
        if not seen[idx]:
            seen[idx] = 1
            heapq.heappush(frontier, (strengths[idx], idx))

    if P > 0:
        add(P - 1, Q)
    if P + 1 < H:
        add(P + 1, Q)
    if Q > 0:
        add(P, Q - 1)
    if Q + 1 < W:
        add(P, Q + 1)

    while frontier and frontier[0][0] * X < power:
        value, idx = heapq.heappop(frontier)
        power += value
        r, c = divmod(idx, W)
        if r > 0:
            add(r - 1, c)
        if r + 1 < H:
            add(r + 1, c)
        if c > 0:
            add(r, c - 1)
        if c + 1 < W:
            add(r, c + 1)

    print(power)


if __name__ == '__main__':
    main()

