import sys

# Mountain at crease x (1-indexed) iff the bit immediately above
# the least significant set bit of x is zero.

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    A = data[1:1+n]

    # Search prefixes of i, from low bits upwards. A term is determined
    # as soon as its first set bit and the following bit are known.
    # Prefixes which can still have an unresolved term are among the
    # residues -A modulo the current power of two.
    best = 0
    states = {0: 0}  # residue -> score of already determined terms
    max_bits = 101
    for b in range(max_bits):
        mod = 1 << (b + 1)
        next_states = {}
        # Retain only prefixes matching a shift modulo mod; all other
        # prefixes resolve every term whose first nonzero bit is low enough.
        for r, score in states.items():
            for bit in (0, 1):
                nr = r + bit * (1 << b)
                val = score
                pending = False
                for a in A:
                    x = (nr + a) % mod
                    if x == 0:
                        pending = True
                        continue
                    # Locate the least significant set bit.
                    t = (x & -x).bit_length() - 1
                    if t + 1 < b + 1:
                        if ((x >> (t + 1)) & 1) == 0:
                            val += 1
                    else:
                        pending = True
                if pending and b < max_bits - 1:
                    next_states[nr] = max(next_states.get(nr, -1), val)
                else:
                    best = max(best, val)
        states = next_states
        if not states:
            break
    print(best)

if __name__ == '__main__':
    main()

