import math

N = int(input())
answer = None

# Let d = x - y. Then N = d(3y^2 + 3dy + d^2), and necessarily d^3 < N.
for d in range(1, 1_000_001):
    if d * d * d >= N:
        break
    if N % d != 0:
        continue

    # With t = 2y + d, 3t^2 = 4(N/d) - d^2.
    value = 4 * (N // d) - d * d
    if value < 0 or value % 3 != 0:
        continue
    square = value // 3
    t = math.isqrt(square)
    if t * t != square or (t - d) % 2:
        continue

    y = (t - d) // 2
    if y > 0:
        answer = (y + d, y)
        break

if answer is None:
    print(-1)
else:
    print(*answer)

