class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        sys.setrecursionlimit(10000)
        n, m = len(grid), len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        @lru_cache(None)
        def extend(r: int, c: int, d: int, expected: int, turned: bool) -> int:
            """Maximum number of additional cells after (r, c)."""
            best = 0
            directions = [d]
            if not turned:
                directions.append((d + 1) % 4)

            for nd in directions:
                dr, dc = dirs[nd]
                nr, nc = r + dr, c + dc
                if (0 <= nr < n and 0 <= nc < m
                        and grid[nr][nc] == expected):
                    best = max(
                        best,
                        1 + extend(nr, nc, nd, 2 if expected == 0 else 0,
                                   turned or nd != d)
                    )
            return best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    for d in range(4):
                        answer = max(answer, 1 + extend(r, c, d, 2, False))
        return answer

