from typing import List
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
        available = list(range(1, n + 1))
        ans = []

        def ways(c0, c1, need):
            total = c0 + c1
            if need == 0:
                slots0 = (total + 1) // 2
                slots1 = total // 2
            else:
                slots1 = (total + 1) // 2
                slots0 = total // 2
            if c0 != slots0 or c1 != slots1:
                return 0
            return fact[c0] * fact[c1]

        while available:
            chosen = None
            for x in available:
                c0 = sum(1 for y in available if y % 2 == 0) - (x % 2 == 0)
                c1 = sum(1 for y in available if y % 2 == 1) - (x % 2 == 1)
                # Need parity opposite x for the next position
                w = ways(c0, c1, 1 - (x % 2))
                if k > w:
                    k -= w
                else:
                    chosen = x
                    break
            if chosen is None:
                return []
            ans.append(chosen)
            available.remove(chosen)
        return ans

