class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        allmask = (1 << k) - 1

        # Contribution to the number modulo k from each mirrored digit.
        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            if i == j:
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[j]) % k)

        def rotate(mask, shift):
            if shift == 0:
                return mask
            return ((mask << shift) | (mask >> (k - shift))) & allmask

        # suffix[i] is the set of residues achievable by digits i onward.
        # The first digit is restricted to 1..9 to prevent leading zeroes.
        suffix = [0] * (m + 1)
        suffix[m] = 1  # residue zero
        for i in range(m - 1, -1, -1):
            choices = 0
            low = 1 if i == 0 else 0
            for digit in range(low, 10):
                choices |= rotate(suffix[i + 1], digit * coeff[i] % k)
            suffix[i] = choices

        # Fix digits from left to right, choosing the largest feasible one.
        used = 0
        left = []
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for digit in range(9, low - 1, -1):
                needed = (-(used + digit * c)) % k
                if (suffix[i + 1] >> needed) & 1:
                    left.append(str(digit))
                    used = (used + digit * c) % k
                    break

        half = ''.join(left)
        if n % 2:
            return half + half[:-1][::-1]
        return half + half[::-1]

