from typing import List
from array import array


class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # next_greater[i] is the first index to the right with a strictly
        # greater value. Prefix maxima starting at i change only at these indices.
        next_greater = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                next_greater[i] = stack[-1]
            stack.append(i)

        levels = n.bit_length()
        jumps = [array('i', next_greater)]
        weights = [array('q', (
            nums[i] * (next_greater[i] - i) if next_greater[i] < n else 0
            for i in range(n)
        ))]

        for _ in range(1, levels):
            prev_jump = jumps[-1]
            prev_weight = weights[-1]
            curr_jump = array('i', [n]) * n
            curr_weight = array('q', [0]) * n
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    curr_jump[i] = prev_jump[mid]
                    curr_weight[i] = prev_weight[i] + prev_weight[mid]
                else:
                    curr_weight[i] = prev_weight[i]
            jumps.append(curr_jump)
            weights.append(curr_weight)

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        def cost(left: int, right: int) -> int:
            # Sum the prefix maxima over [left, right].
            node = left
            total = 0
            for level in range(levels - 1, -1, -1):
                dest = jumps[level][node]
                if dest <= right:
                    total += weights[level][node]
                    node = dest
            total += nums[node] * (right - node + 1)
            return total - (prefix[right + 1] - prefix[left])

        answer = 0
        for right in range(n):
            lo, hi = 0, right
            # Feasibility is monotone in the left endpoint: removing a prefix
            # cannot increase the number of increments needed.
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(mid, right) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1

        return answer

