class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        n = len(s)
        # For a fixed final frequency, process letters from left to right.
        # The state is the number of characters arriving from the previous letter.
        answer = n
        for target in range(1, max(cnt) + 1):
            dp = {0: 0}
            for i in range(26):
                c = cnt[i]
                ndp = {}
                for incoming, base in dp.items():
                    available = c + incoming
                    # Choose how many characters to advance to the next letter.
                    for outgoing in range(available + 1):
                        remain = available - outgoing
                        cost0 = base + outgoing + remain  # make this letter absent
                        if cost0 < ndp.get(outgoing, n + 1):
                            ndp[outgoing] = cost0
                        # Or make its final count equal to target, using insertions/deletions.
                        cost = base + outgoing + abs(remain - target)
                        if cost < ndp.get(outgoing, n + 1):
                            ndp[outgoing] = cost
                dp = ndp
            answer = min(answer, dp.get(0, n))
        return answer

