import sys
MOD = 998244353

def solve(H, W, S):
    # The parity equations for horizontal/vertical edges require even A-counts
    # in every row and column.
    col_parity = [0] * W
    for row in S:
        for j, ch in enumerate(row):
            if ch == 'A':
                col_parity[j] ^= 1
        if sum(ch == 'A' for ch in row) & 1:
            return 0
    if any(col_parity):
        return 0

    # One free bit per row gives its horizontal edges; one per column gives
    # its vertical edges. B cells impose xor equalities between these bits.
    n = H + W
    parent = list(range(n))
    xr = [0] * n  # xor from node to parent

    def find(a):
        if parent[a] != a:
            p = parent[a]
            parent[a] = find(p)
            xr[a] ^= xr[p]
        return parent[a]

    def unite(a, b, value):
        ra, rb = find(a), find(b)
        xa, xb = xr[a], xr[b]
        if ra == rb:
            return (xa ^ xb) == value
        parent[ra] = rb
        xr[ra] = xa ^ xb ^ value
        return True

    below = [0] * W  # parity of A cells strictly below current row
    for i in range(H - 1, -1, -1):
        suffix = 0  # parity of A cells strictly to the right
        row = S[i]
        for j in range(W - 1, -1, -1):
            if row[j] == 'B':
                # At B, the horizontal and vertical pair must be opposite.
                if not unite(i, H + j, 1 ^ suffix ^ below[j]):
                    return 0
            elif row[j] == 'A':
                suffix ^= 1
        for j, ch in enumerate(row):
            if ch == 'A':
                below[j] ^= 1

    components = sum(find(i) == i for i in range(n))
    return pow(2, components, MOD)


