from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            # KMP prefix function
            prefix = [0] * len(t)
            j = 0
            for i in range(1, len(t)):
                while j and t[i] != t[j]:
                    j = prefix[j - 1]
                if t[i] == t[j]:
                    j += 1
                prefix[i] = j

            found = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = prefix[j - 1]
                if ch == t[j]:
                    j += 1
                if j == len(t):
                    found.append(i - len(t) + 1)
                    j = prefix[j - 1]
            return found

        starts_a = occurrences(a)
        starts_b = occurrences(b)
        starts_c = occurrences(c)

        best = n + 1
        for start in starts_a:
            ib = bisect_left(starts_b, start + len(a))
            if ib == len(starts_b):
                continue
            start_b = starts_b[ib]

            ic = bisect_left(starts_c, start_b + len(b))
            if ic == len(starts_c):
                continue
            end_c = starts_c[ic] + len(c)
            best = min(best, end_c - start)

        return best if best <= n else -1

