def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    k = 2
    for _ in range(m):
        x, y, z = data[k] - 1, data[k + 1] - 1, data[k + 2]
        k += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    potential = [None] * n
    answer = [0] * n
    for start in range(n):
        if potential[start] is not None:
            continue
        potential[start] = 0
        stack = [start]
        component = []
        consistent = True
        while stack:
            v = stack.pop()
            component.append(v)
            for u, z in adj[v]:
                required = potential[v] ^ z
                if potential[u] is None:
                    potential[u] = required
                    stack.append(u)
                elif potential[u] != required:
                    consistent = False
