from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for node in range(1, n):
            children[parent[node]].append(node)

        # Build the postorder iteratively, recording each subtree's interval.
        order = []
        start = [0] * n
        end = [0] * n  # exclusive
        stack = [(0, False)]
        while stack:
            node, visited = stack.pop()
            if visited:
                order.append(s[node])
                end[node] = len(order)
            else:
                start[node] = len(order)
                stack.append((node, True))
                for child in reversed(children[node]):
                    stack.append((child, False))

        text = ''.join(order)
        m = len(text)

        # Manacher radii: odd[i] includes the center; even[i] is centered
        # between i-1 and i.
        odd = [0] * m
        left, right = 0, -1
        for i in range(m):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < m and text[i - radius] == text[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        even = [0] * m
        left, right = 0, -1
        for i in range(m):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < m and text[i - radius - 1] == text[i + radius]:
                radius += 1
            even[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = [False] * n
        for node in range(n):
            a, b = start[node], end[node] - 1
            length = b - a + 1
            if length % 2:
                answer[node] = odd[(a + b) // 2] >= length // 2 + 1
            else:
                answer[node] = even[(a + b + 1) // 2] >= length // 2
        return answer

