import sys
from bisect import bisect_right

N = int(sys.stdin.buffer.readline())
M = int(N ** 0.5)
while (M + 1) * (M + 1) <= N:
    M += 1
while M * M > N:
    M -= 1

sieve = bytearray(b'\x01') * (M + 1)
if M >= 0:
    sieve[0] = 0
if M >= 1:
    sieve[1] = 0
for i in range(2, int(M ** 0.5) + 1):
    if sieve[i]:
        sieve[i * i:M + 1:i] = b'\x00' * (((M - i * i) // i) + 1)
primes = [i for i in range(2, M + 1) if sieve[i]]

answer = 0
# Count p^2 q^2 <= N, equivalently p*q <= floor(sqrt(N)), for p < q.
for i, p in enumerate(primes):
    if p * p > M:
        break
    answer += bisect_right(primes, M // p) - i - 1

# The remaining divisor-count pattern is p^8.
for p in primes:
    if p ** 8 <= N:
        answer += 1
    else:
        break

print(answer)

