from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        counts = Counter(nums)
        for x in sorted(counts, reverse=True):
            remainder = total - x
            if remainder % 2:
                continue
            y = remainder // 2
            if counts[y] > (1 if y == x else 0):
                return x
        # The statement guarantees an answer.

