class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        # Sieve primes in the range reachable from the given four-digit bound.
        limit = 10**4
        prime = bytearray(b'\x01') * limit
        prime[0:2] = b'\x00\x00'
        for p in range(2, 100):
            if prime[p]:
                start = p * p
                count = (limit - 1 - start) // p + 1
                prime[start:limit:p] = b'\x00' * count

        if prime[n] or prime[m]:
            return -1

        # A node's distance includes its own value, so initialize with n.
        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist.get(x):
                continue
            if x == m:
                return cost

            digits = str(x)
            for i, char in enumerate(digits):
                digit = ord(char) - 48
                place = 10 ** (len(digits) - 1 - i)
                for new_digit in (digit - 1, digit + 1):
                    if not 0 <= new_digit <= 9:
                        continue
                    # Do not create a leading zero; the integer then has fewer digits.
                    if i == 0 and len(digits) > 1 and new_digit == 0:
                        continue
                    nxt = x + (new_digit - digit) * place
                    if prime[nxt]:
                        continue
                    new_cost = cost + nxt
                    if new_cost < dist.get(nxt, float('inf')):
                        dist[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))
        return -1

