from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # z[i] is the LCP length of nums and nums[i:]
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        # For each starting position i of nums2, calculate LCP(i, j)
        # for every j > i. dp[j] stores LCP(i+1, j) before the row update.
        dp = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            second_condition = 0
            overlap = 0
            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    common = 1 + dp[j + 1]
                else:
                    common = 0
                dp[j] = common

                if common >= j - i:
                    second_condition += 1
                    if j >= 2 * i:
                        overlap += 1

            if z[i] >= i:
                # nums1 is a prefix of nums2. nums2 must be at least i long.
                first_condition_count = max(0, n - 2 * i)
                answer += second_condition + first_condition_count - overlap
            else:
                answer += second_condition

        return answer

