    answer = 0 if n % 2 == 0 else None  # the empty final stack

    for i, x in enumerate(a):
        p = i & 1
        cur = x if p == 0 else None  # a survivor sequence must start at index 0
        if best[1 - p] is not None:
            candidate = best[1 - p] + x
            if cur is None or candidate > cur:
