from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0
        targets = set(targetIndices)

        for i, ch in enumerate(source):
            # Keeping this character without using it for the pattern is always allowed.
            nxt = dp[:]

            # Or remove it, if its original index is eligible.
            if i in targets:
                for j, value in enumerate(dp):
                    if value != neg:
                        nxt[j] = max(nxt[j], value + 1)

            # Or keep it and use it to match the next pattern character.
            for j in range(m):
                if ch == pattern[j] and dp[j] != neg:
                    nxt[j + 1] = max(nxt[j + 1], dp[j])

            dp = nxt

        return dp[m]

