from typing import List
import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reverse each edge so paths found from 0 correspond to paths ending at 0.
        rev = [[] for _ in range(n)]
        for a, b, w in edges:
            rev[b].append((a, w))

        inf = 10**18
        bottleneck = [inf] * n
        bottleneck[0] = 0
        pq = [(0, 0)]

        while pq:
            cost, node = heapq.heappop(pq)
            if cost != bottleneck[node]:
                continue
            for prev, weight in rev[node]:
                candidate = max(cost, weight)
                if candidate < bottleneck[prev]:
                    bottleneck[prev] = candidate
                    heapq.heappush(pq, (candidate, prev))

        answer = max(bottleneck)
        return -1 if answer == inf else answer

