from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        inf = 10**30
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        for i in range(1, n // 2):
            ndp = [inf] * 6
            for x, (a, b) in enumerate(states):
                pair_cost = cost[i][a] + cost[n - 1 - i][b]
                for y, (pa, pb) in enumerate(states):
                    if a != pa and b != pb:
                        candidate = dp[y] + pair_cost
                        if candidate < ndp[x]:
                            ndp[x] = candidate
            dp = ndp

        return min(dp)

